def _parse(version):
    """Return a sortable key for a semantic version string."""
    # Build metadata is ignored for precedence.
    without_build = version.split("+", 1)[0]

    if "-" in without_build:
        core, prerelease = without_build.split("-", 1)
    else:
        core, prerelease = without_build, None

    major, minor, patch = (int(part) for part in core.split("."))

    if prerelease is None:
        # A normal version has higher precedence than any pre-release.
        prerelease_key = (1, ())
    else:
        identifiers = []
        for identifier in prerelease.split("."):
            if identifier.isdigit():
                identifiers.append((0, int(identifier)))
            else:
                # Alphanumeric identifiers sort after numeric identifiers and
                # are compared in ASCII order.
                identifiers.append((1, identifier))
        prerelease_key = (0, tuple(identifiers))

    return (major, minor, patch) + prerelease_key


def sort_versions(vs):
    """Return semantic version strings sorted by precedence, lowest first.

    Sorting is stable, so versions that tie keep their input order.
    """
